import 'package:flutter/material.dart';

import '../../core/constants/app_colors.dart';
import '../../core/constants/app_strings.dart';
import '../../core/constants/brand_mark.dart';
import '../../core/theme/app_decorations.dart';
import '../../core/theme/app_theme.dart';

/// The KashU app icon as the app draws it: a cream cashew catching a gold
/// coin on the lavender tile. Same geometry as the launcher icons, from
/// [BrandMark] (generated by tool/generate_brand_assets.py).
class KashuMark extends StatelessWidget {
  const KashuMark({super.key, this.size = 88, this.glow = false});

  final double size;

  /// Adds the soft lavender glow used where the mark stands alone (the
  /// lock screen, onboarding, Settings › About).
  final bool glow;

  @override
  Widget build(BuildContext context) {
    final mark = CustomPaint(
      size: Size.square(size),
      painter: const _MarkPainter(),
    );
    return Semantics(
      label: '${AppStrings.appName} logo',
      image: true,
      child: glow
          ? DecoratedBox(
              decoration: BoxDecoration(
                borderRadius: BorderRadius.circular(
                    size * BrandMark.tileCornerRadius / 100),
                boxShadow:
                    AppShadows.glow(AppColors.brandLavender, opacity: 0.5),
              ),
              child: mark,
            )
          : mark,
    );
  }
}

/// "Kash" set in the heading font, followed by the cashew-and-coin U.
/// Deep ink with a lavender U on light grounds, cream with a pale U on dark.
class KashuWordmark extends StatelessWidget {
  const KashuWordmark({super.key, required this.fontSize});

  final double fontSize;

  @override
  Widget build(BuildContext context) {
    final dark = Theme.of(context).brightness == Brightness.dark;
    final glyphHeight = fontSize * BrandMark.glyphHeightPerEm;
    final box = BrandMark.glyphBox;
    return Semantics(
      label: AppStrings.appName,
      excludeSemantics: true,
      child: Text.rich(
        TextSpan(
          text: 'Kash',
          style: AppTheme.heading(
            size: fontSize,
            color: dark ? AppColors.brandCream : AppColors.brandInk,
          ),
          children: [
            // No baseline of its own, so the U's bottom sits on the text
            // baseline, like a capital letter.
            WidgetSpan(
              alignment: PlaceholderAlignment.baseline,
              baseline: TextBaseline.alphabetic,
              child: Padding(
                padding: EdgeInsets.only(left: fontSize * 0.06),
                child: CustomPaint(
                  size: Size(glyphHeight * box.width / box.height, glyphHeight),
                  painter: _MarkPainter(
                    tile: false,
                    nutColor:
                        dark ? AppColors.brandPaper : AppColors.brandLavender,
                    box: box,
                  ),
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

class _MarkPainter extends CustomPainter {
  const _MarkPainter({
    this.tile = true,
    this.nutColor = AppColors.brandCream,
    this.box = const Rect.fromLTWH(0, 0, 100, 100),
  });

  final bool tile;
  final Color nutColor;

  /// The part of the 100 × 100 design space drawn into the widget.
  final Rect box;

  @override
  void paint(Canvas canvas, Size size) {
    canvas
      ..save()
      ..scale(size.width / box.width, size.height / box.height)
      ..translate(-box.left, -box.top);
    if (tile) {
      canvas.drawRRect(
        RRect.fromRectAndRadius(
          const Rect.fromLTWH(0, 0, 100, 100),
          const Radius.circular(BrandMark.tileCornerRadius),
        ),
        Paint()..color = AppColors.brandLavender,
      );
    }
    canvas
      ..drawPath(BrandMark.nutPath(), Paint()..color = nutColor)
      ..drawCircle(BrandMark.coinCenter, BrandMark.coinRadius,
          Paint()..color = AppColors.brandGold)
      ..restore();
  }

  @override
  bool shouldRepaint(_MarkPainter old) =>
      old.tile != tile || old.nutColor != nutColor || old.box != box;
}
